#!/bin/bash
# Generated by OpenAI Codex on 2026-11-01. Install reviewed files before running.
set -euo pipefail
[[ $(id -u) == 0 ]]
getent group cats-upload >/dev/null || groupadd cats-upload
install -d -m 755 /var/empty/cats-users /etc/ssh/cats-keys
install -d -m 700 /var/lib/cats-control /var/lib/cats-backups
for name in parker carter anna becca sadia vincent; do
  id "cats-$name" >/dev/null 2>&1 || useradd --no-create-home --home-dir "/var/empty/cats-users/$name" --shell /bin/dash --groups cats-upload "cats-$name"
  install -d -m 755 -o root -g root "/var/empty/cats-users/$name"
done
cat > /etc/ssh/sshd_config.d/40-cats-upload.conf <<'EOF'
Match Group cats-upload
    AuthorizedKeysFile /etc/ssh/cats-keys/%u
    ForceCommand /usr/local/libexec/cats-ssh
    DisableForwarding yes
    PermitTTY no
    PermitUserRC no
    PasswordAuthentication no
    KbdInteractiveAuthentication no
    AuthenticationMethods publickey
Match all
EOF
cat > /etc/sudoers.d/cats-upload <<'EOF'
%cats-upload ALL=(root) NOPASSWD: /usr/local/libexec/cats-command *
EOF
chmod 440 /etc/sudoers.d/cats-upload
visudo -cf /etc/sudoers.d/cats-upload
sshd -t
systemctl reload ssh
